export interface UiFeature {
  /** Route (`/skills`), or `token`/`shell` for the sign-in screen and the app frame. */
  screen: string;
  feature: string;
  /** Files under `web/src` that make these calls. */
  sources: string[];
  calls: CallName[];
  /** Only for features without any daemon call: why none is needed. */
  clientOnly?: string;
}

